export enum ProjectRevisionAction {
	FIX_CHANGE = 'FIX_CHANGE',
	TRY_AGAIN = 'TRY_AGAIN',
	PROMPT_CHANGE = 'PROMPT_CHANGE',
	UI_PATCH = 'UI_PATCH',
	CREATE_COMPONENT_FROM_PROMPT = 'CREATE_COMPONENT_FROM_PROMPT',
	CREATE_COMPONENT_FROM_PROMPT_AND_CODE = 'CREATE_COMPONENT_FROM_PROMPT_AND_CODE',
	DELETION = 'DELETION',
	TEXT_CHANGE = 'TEXT_CHANGE',
	IMAGE_CHANGE = 'IMAGE_CHANGE',
	LINK_CHANGE = 'LINK_CHANGE',
	/**
	 * @deprecated
	 */
	FORM_CHANGE = 'FORM_CHANGE',
	/**
	 * @deprecated - use APPLY_COMMAND instead
	 */
	COMMENT_CHANGE = 'COMMENT_CHANGE',
	RESTORE = 'RESTORE',
	CHANGE_AUTH = 'CHANGE_AUTH',
	CODE_CHANGE = 'CODE_CHANGE',
	APPLY_COMMAND = 'APPLY_COMMAND',
	SELECT_INITIAL_MODULE_IDEA = 'SELECT_INITIAL_MODULE_IDEA',
	AUTOFIX_CHANGE = 'AUTOFIX_CHANGE',
	ENHANCE_PROMPT = 'ENHANCE_PROMPT',
	CHAT = 'CHAT',
	TOP_DOWN_CHAT = 'TOP_DOWN_CHAT',
	REBUILD_FROM_LATEST = 'REBUILD_FROM_LATEST',
	UPDATE_REFERENCES = 'UPDATE_REFERENCES',
	FORK_FROM_PROJECT_GROUP_TEMPLATE = 'FORK_FROM_PROJECT_GROUP_TEMPLATE',
	FORK_FROM_PROJECT_GROUP = 'FORK_FROM_PROJECT_GROUP',
	DUPLICATE_PROJECT_GROUP = 'DUPLICATE_PROJECT_GROUP',
	FORK_FROM_MODULE = 'FORK_FROM_MODULE',
	DUPLICATE_MODULE = 'DUPLICATE_MODULE',
	AGENT_AUTO_SELECT_INTEGRATION = 'AGENT_AUTO_SELECT_INTEGRATION',
	INITIAL = 'INITIAL'
}

/**
 * Returns true if the action indicates that the revision associated with this
 * action has a spec for the prompt field.
 *
 * This can be used to determine which revisions can be safely referenced to
 * populate the spec from the prompt field.
 */
export const isActionIndicatingRevisionHasSpecForPrompt = (
	action: ProjectRevisionAction
) => {
	switch (action) {
		case ProjectRevisionAction.PROMPT_CHANGE:
		case ProjectRevisionAction.TRY_AGAIN:
		case ProjectRevisionAction.CREATE_COMPONENT_FROM_PROMPT:
		case ProjectRevisionAction.CREATE_COMPONENT_FROM_PROMPT_AND_CODE:
		case ProjectRevisionAction.FIX_CHANGE:
		case ProjectRevisionAction.RESTORE:
		case ProjectRevisionAction.UI_PATCH:
		case ProjectRevisionAction.APPLY_COMMAND:
		case ProjectRevisionAction.SELECT_INITIAL_MODULE_IDEA:
		case ProjectRevisionAction.ENHANCE_PROMPT:
		case ProjectRevisionAction.AUTOFIX_CHANGE:
		case ProjectRevisionAction.CHANGE_AUTH:
		case ProjectRevisionAction.CODE_CHANGE:
		case ProjectRevisionAction.DELETION:
		case ProjectRevisionAction.IMAGE_CHANGE:
		case ProjectRevisionAction.LINK_CHANGE:
		case ProjectRevisionAction.TEXT_CHANGE:
		case ProjectRevisionAction.CHAT:
		case ProjectRevisionAction.TOP_DOWN_CHAT:
		case ProjectRevisionAction.REBUILD_FROM_LATEST:
		case ProjectRevisionAction.UPDATE_REFERENCES:
		case ProjectRevisionAction.FORK_FROM_PROJECT_GROUP_TEMPLATE:
		case ProjectRevisionAction.FORK_FROM_PROJECT_GROUP:
		case ProjectRevisionAction.DUPLICATE_PROJECT_GROUP:
		case ProjectRevisionAction.DUPLICATE_MODULE:
		case ProjectRevisionAction.FORK_FROM_MODULE:
		case ProjectRevisionAction.AGENT_AUTO_SELECT_INTEGRATION:
			return true
		case ProjectRevisionAction.COMMENT_CHANGE:
		case ProjectRevisionAction.FORM_CHANGE:
		case ProjectRevisionAction.INITIAL:
			return false
		default: {
			const exhaustiveCheck: never = action
			return exhaustiveCheck
		}
	}
}

export enum ProjectRevisionStatus {
	QUEUED = 'QUEUED',
	GENERATION_FAILED = 'GENERATION_FAILED',
	/**
	 * Indicates that the revision is in a state where we attempted generation
	 * but something about the data we were passing into the generation failed
	 * for it to generate (usually the prompt contains information that is
	 * unusable).
	 */
	INVALID_PROMPT = 'INVALID_PROMPT',
	/**
	 * This should only be used when the revision is created but generation has
	 * not started.
	 * If a revision does not expect generation, you should instead use VALID.
	 */
	CREATED = 'CREATED',
	/**
	 * This should only be used when the revision is created, generation is done
	 * (if necessary) and the code is valid.
	 */
	VALID = 'VALID',
	/**
	 * This should only be used when the revision is created, generation is
	 * done and the code is invalid.
	 */
	INVALID = 'INVALID',
	BUILDING = 'BUILDING',
	BUILDING_UI = 'BUILDING_UI',
	BUILDING_FUNCTIONALITY = 'BUILDING_FUNCTIONALITY',
	INVALID_CODE = 'INVALID_CODE',
	CANCELED_AUTOFIX = 'CANCELED_AUTOFIX',
	ENHANCING_PROMPT = 'ENHANCING_PROMPT',

	/**
	 * Indicates that the revision failed
	 */
	FAILED = 'FAILED'
}

export const PROJECT_BUILDING_STATUSES = [
	ProjectRevisionStatus.BUILDING,
	ProjectRevisionStatus.BUILDING_UI,
	ProjectRevisionStatus.BUILDING_FUNCTIONALITY
] as const

export const PROJECT_GROUP_BUILDING_STATUSES = [
	ProjectGroupRevisionStatus.BUILDING
]

const BUILDING_STATUSES_SET = new Set<
	ProjectRevisionStatus | ProjectGroupRevisionStatus
>([...PROJECT_BUILDING_STATUSES, ...PROJECT_GROUP_BUILDING_STATUSES])

export const GENERATION_FINISHED_STATUSES = Object.values(
	ProjectRevisionStatus
).filter((status) => !BUILDING_STATUSES_SET.has(status))

export const isStatusIndicatingRevisionIsBuilding = (
	status: ProjectRevisionStatus | ProjectGroupRevisionStatus
): status is (typeof PROJECT_BUILDING_STATUSES)[number] =>
	BUILDING_STATUSES_SET.has(status)

